#include <iostream>
#include <vector>
#include <string>
using namespace std;
const int MAXN = 100001;
long long tree[4*MAXN], lazy[4*MAXN];
int N;
void build(vector<int>& a, int node, int lo, int hi){
    lazy[node]=-1;
    if(lo==hi){tree[node]=a[lo-1];return;}
    int mid=(lo+hi)/2;
    build(a,2*node,lo,mid); build(a,2*node+1,mid+1,hi);
    tree[node]=tree[2*node]+tree[2*node+1];
}
void push(int node, int lo, int hi){
    if(lazy[node]!=-1){
        int mid=(lo+hi)/2;
        tree[2*node]=lazy[node]*(mid-lo+1); lazy[2*node]=lazy[node];
        tree[2*node+1]=lazy[node]*(hi-mid); lazy[2*node+1]=lazy[node];
        lazy[node]=-1;
    }
}
void update(int node,int lo,int hi,int l,int r,long long v){
    if(r<lo||hi<l) return;
    if(l<=lo&&hi<=r){tree[node]=v*(hi-lo+1);lazy[node]=v;return;}
    push(node,lo,hi);
    int mid=(lo+hi)/2;
    update(2*node,lo,mid,l,r,v); update(2*node+1,mid+1,hi,l,r,v);
    tree[node]=tree[2*node]+tree[2*node+1];
}
long long query(int node,int lo,int hi,int l,int r){
    if(r<lo||hi<l) return 0;
    if(l<=lo&&hi<=r) return tree[node];
    push(node,lo,hi);
    int mid=(lo+hi)/2;
    return query(2*node,lo,mid,l,r)+query(2*node+1,mid+1,hi,l,r);
}
int main(){
    int q; cin>>N>>q;
    vector<int> a(N);
    for(int i=0;i<N;i++) cin>>a[i];
    build(a,1,1,N);
    while(q--){
        string op; cin>>op;
        if(op=="A"){int l,r,v;cin>>l>>r>>v;update(1,1,N,l,r,v);}
        else{int l,r;cin>>l>>r;cout<<query(1,1,N,l,r)<<"\n";}
    }
}

